<script setup lang="ts">
import {onMounted,ref} from 'vue'
import axios from 'axios'
const props=defineProps<{token:string}>(),emit=defineEmits<{unauthorized:[]}>()
const api=axios.create({baseURL:import.meta.env.VITE_API_URL||'http://localhost:8000'})
const rows=ref<any[]>([]),manifest=ref(''),file=ref<File|null>(null),enabled=ref(false),busy=ref(false),error=ref(''),notice=ref('')
const auth=()=>({headers:{Authorization:`Bearer ${props.token}`}})
async function perform(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';try{await fn()}catch(e:any){if(e.response?.status===401)emit('unauthorized');error.value=e.response?.data?.detail||'发布管理请求失败'}finally{busy.value=false}}
async function load(){rows.value=(await api.get('/hub-v5/releases',auth())).data}
async function publish(){await perform(async()=>{if(!file.value)return;const body=new FormData();body.append('manifest_json',manifest.value);body.append('enabled',String(enabled.value));body.append('artifact',file.value);await api.post('/hub-v5/releases',body,auth());notice.value='签名包已校验并上传';await load()})}
async function disable(id:number){await perform(async()=>{await api.post(`/hub-v5/releases/${id}/disable`,{},auth());notice.value='已停止分发';await load()})}
onMounted(()=>void perform(load))
</script>
<template><div class="matrix-releases"><p>上传已签名的连接器或站点插件。设备仍会校验签名与兼容性。</p><p v-if="error" class="mr-error" role="alert">{{error}}</p><p v-if="notice" class="mr-notice" role="status">{{notice}}</p><form @submit.prevent="publish"><label>签名清单 JSON<textarea v-model="manifest" required rows="5"/></label><label>发布包 ZIP<input type="file" accept=".zip" required @change="file=($event.target as HTMLInputElement).files?.[0]||null"/></label><div class="mr-actions"><label class="mr-check"><input v-model="enabled" type="checkbox"/>上传后向本公司设备开放</label><button :disabled="busy||!file">{{busy?'处理中…':'校验并上传'}}</button></div></form><div v-for="r in rows" :key="r.id" class="mr-row"><div><b>{{r.manifest.kind==='agent'?'连接器':'站点插件'}} {{r.manifest.version}}</b><small>{{r.manifest.platform}} / {{r.manifest.arch}} · {{r.enabled?'已开放':'已停用'}}</small></div><button v-if="r.enabled" :disabled="busy" @click="disable(r.id)">停止分发</button></div><p v-if="!rows.length" class="mr-empty">暂无已发布版本</p></div></template>
<style scoped>
.matrix-releases{font-size:12px;color:#727b8e}.matrix-releases p{margin:0 0 14px;line-height:1.7}.matrix-releases form{display:grid;gap:12px}.matrix-releases label{display:flex;flex-direction:column;gap:7px;font-size:12px}.matrix-releases textarea,.matrix-releases input[type=file]{box-sizing:border-box;width:100%;margin:0;padding:9px 10px;border:1px solid #dfe2eb;border-radius:6px;background:#fff;color:inherit;font:inherit}.matrix-releases textarea{resize:vertical}.mr-actions,.mr-row{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:10px}.mr-actions .mr-check{flex-direction:row;align-items:center}.mr-check input{width:14px;height:14px;margin:0;accent-color:#6043d4}.matrix-releases button{min-height:32px;padding:5px 11px;border:1px solid #dfe2eb;border-radius:6px;background:#fff;color:#6043d4;font:inherit;cursor:pointer}.matrix-releases button:disabled{opacity:.5}.mr-row{margin-top:12px;padding:12px;border:1px solid #e5e7ee;border-radius:6px}.mr-row b{font-size:12px;font-weight:500}.mr-row small{display:block;margin-top:5px;color:#8a92a2}.mr-error{color:#b84a51}.mr-notice{color:#338260}.mr-empty{padding:16px;text-align:center;color:#9aa1af}
</style>
